package claudecookie

import (
	"errors"
	"strings"
	"testing"
	"time"
)

// reference is the shape Cookie-Editor produces for a claude.ai export: a
// Netscape header, an #HttpOnly_ prefixed line, tab separated fields, and both
// sessionKey and sessionKeyV3 present.
const netscapeExport = "# Netscape HTTP Cookie File\n" +
	"# http://curl.haxx.se/rfc/cookie_spec.html\n" +
	"# This file was generated by Cookie-Editor\n" +
	"#HttpOnly_.claude.ai\tTRUE\t/\tTRUE\t4000000000\t__cf_bm\tcfvalue\n" +
	"claude.ai\tFALSE\t/\tTRUE\t4000000000\tanthropic-device-id\tdev-1\n" +
	".claude.ai\tTRUE\t/\tTRUE\t4000000000\tsessionKey\tsk-ant-sid02-primary\n" +
	".claude.ai\tTRUE\t/\tTRUE\t4000000000\tsessionKeyV3\tsk-ant-sid02-v3\n" +
	".claude.ai\tTRUE\t/\tTRUE\t4000000000\tlastActiveOrg\torg-1\n"

func TestParseOneNetscape(t *testing.T) {
	got, err := ParseOne(netscapeExport)
	if err != nil {
		t.Fatalf("ParseOne() error = %v", err)
	}

	if got.SessionKey != "sk-ant-sid02-primary" {
		t.Errorf("SessionKey = %q, want the sessionKey cookie value", got.SessionKey)
	}
	if len(got.Names) != 5 {
		t.Errorf("Names = %v, want 5 cookies", got.Names)
	}
	// The jar must be a sendable Cookie header preserving file order.
	wantJar := "__cf_bm=cfvalue; anthropic-device-id=dev-1; sessionKey=sk-ant-sid02-primary; " +
		"sessionKeyV3=sk-ant-sid02-v3; lastActiveOrg=org-1"
	if got.Jar != wantJar {
		t.Errorf("Jar =\n  %q\nwant\n  %q", got.Jar, wantJar)
	}
}

func TestParseOneNetscapeDropsExpiredCookies(t *testing.T) {
	// __cf_bm is short lived; a browser would not replay an expired one.
	raw := "#HttpOnly_.claude.ai\tTRUE\t/\tTRUE\t1000000000\t__cf_bm\tstale\n" +
		".claude.ai\tTRUE\t/\tTRUE\t4000000000\tsessionKey\tsk-ant-sid02-fresh\n"

	got, err := ParseOne(raw)
	if err != nil {
		t.Fatalf("ParseOne() error = %v", err)
	}
	if strings.Contains(got.Jar, "__cf_bm") {
		t.Errorf("Jar = %q, want expired __cf_bm dropped", got.Jar)
	}
	if got.SessionKey != "sk-ant-sid02-fresh" {
		t.Errorf("SessionKey = %q", got.SessionKey)
	}
}

func TestParseOneNetscapeKeepsSessionCookies(t *testing.T) {
	// expiry 0 means a session cookie, not an expired one.
	raw := ".claude.ai\tTRUE\t/\tTRUE\t0\ttransient\tkeep\n" +
		".claude.ai\tTRUE\t/\tTRUE\t4000000000\tsessionKey\tsk-ant-sid02-x\n"

	got, err := ParseOne(raw)
	if err != nil {
		t.Fatalf("ParseOne() error = %v", err)
	}
	if !strings.Contains(got.Jar, "transient=keep") {
		t.Errorf("Jar = %q, want session cookie kept", got.Jar)
	}
}

