func TestParseOneErrors(t *testing.T) {
	tests := []struct {
		name string
		raw  string
	}{
		{"empty", "   \n  \n"},
		{"comments only", "# Netscape HTTP Cookie File\n# nothing else\n"},
		{"no session key", "anthropic-device-id=dev-1; lastActiveOrg=org-2"},
		{"netscape without session key", ".claude.ai\tTRUE\t/\tTRUE\t4000000000\tARID\tvalue\n"},
		{"malformed json", "[{\"name\":}]"},
		{"garbage", "hello world this is not a cookie"},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if _, err := ParseOne(tc.raw); !errors.Is(err, ErrNoSessionKey) {
				t.Errorf("ParseOne() error = %v, want ErrNoSessionKey", err)
			}
		})
	}
}

func TestParseManyBatchOfBareKeys(t *testing.T) {
	raw := "sk-ant-sid02-a\n\n  sk-ant-sid02-b  \nsk-ant-sid02-c\n"

	got, err := ParseMany(raw)
	if err != nil {
		t.Fatalf("ParseMany() error = %v", err)
	}
	if len(got) != 3 {
		t.Fatalf("len = %d, want 3 accounts", len(got))
	}
	for i, want := range []string{"sk-ant-sid02-a", "sk-ant-sid02-b", "sk-ant-sid02-c"} {
		if got[i].SessionKey != want {
			t.Errorf("[%d].SessionKey = %q, want %q", i, got[i].SessionKey, want)
		}
		if got[i].Jar != "sessionKey="+want {
			t.Errorf("[%d].Jar = %q", i, got[i].Jar)
		}
	}
}

func TestParseManyTreatsNetscapeAsOneAccount(t *testing.T) {
	// A multi-line Netscape export must not be mistaken for a batch of keys.
	got, err := ParseMany(netscapeExport)
	if err != nil {
		t.Fatalf("ParseMany() error = %v", err)
	}
	if len(got) != 1 {
		t.Fatalf("len = %d, want 1 account", len(got))
	}
	if got[0].SessionKey != "sk-ant-sid02-primary" {
		t.Errorf("SessionKey = %q", got[0].SessionKey)
	}
	if !strings.Contains(got[0].Jar, "lastActiveOrg=org-1") {
		t.Errorf("Jar = %q, want full jar preserved", got[0].Jar)
	}
}

func TestParseManyTreatsJSONAsOneAccount(t *testing.T) {
	raw := `[{"name":"sessionKey","value":"sk-ant-sid02-j"},
	{"name":"lastActiveOrg","value":"org-3"}]`

	got, err := ParseMany(raw)
	if err != nil {
		t.Fatalf("ParseMany() error = %v", err)
	}
	if len(got) != 1 {
		t.Fatalf("len = %d, want 1 account", len(got))
	}
}

func TestParseManyRejectsBatchWhenALineHasNoSessionKey(t *testing.T) {
	raw := "sk-ant-sid02-a\nnot-a-session-key\n"
	if _, err := ParseMany(raw); !errors.Is(err, ErrNoSessionKey) {
		t.Errorf("ParseMany() error = %v, want ErrNoSessionKey", err)
	}
}

func TestJarForSessionKey(t *testing.T) {
	if got := JarForSessionKey("sk-ant-sid02-z"); got != "sessionKey=sk-ant-sid02-z" {
		t.Errorf("JarForSessionKey() = %q", got)
	}
	if got := JarForSessionKey(""); got != "" {
		t.Errorf("JarForSessionKey(\"\") = %q, want empty", got)
	}
}

func TestParseOneIgnoresShortNetscapeLines(t *testing.T) {
	// Wrapped/truncated lines must not corrupt the jar.
	raw := ".claude.ai\tTRUE\t/\n" +
		".claude.ai\tTRUE\t/\tTRUE\t4000000000\tsessionKey\tsk-ant-sid02-ok\n"

	got, err := ParseOne(raw)
	if err != nil {
		t.Fatalf("ParseOne() error = %v", err)
	}
	if got.Jar != "sessionKey=sk-ant-sid02-ok" {
		t.Errorf("Jar = %q", got.Jar)
	}
}

func TestParseOneNetscapeWithSpaceSeparatedFields(t *testing.T) {
	// Some editors mangle tabs into runs of spaces on copy/paste.
	raw := ".claude.ai TRUE / TRUE 4000000000 sessionKey sk-ant-sid02-spaced"

	got, err := ParseOne(raw)
	if err != nil {
		t.Fatalf("ParseOne() error = %v", err)
	}
	if got.SessionKey != "sk-ant-sid02-spaced" {
		t.Errorf("SessionKey = %q", got.SessionKey)
	}
}

func TestParseAtClockBoundary(t *testing.T) {
	now := time.Unix(2_000_000_000, 0)
	raw := ".claude.ai\tTRUE\t/\tTRUE\t1999999999\told\tv1\n" +
		".claude.ai\tTRUE\t/\tTRUE\t2000000001\tsessionKey\tsk-ant-sid02-b\n"

	got, err := parseOneAt(raw, now)
	if err != nil {
		t.Fatalf("parseOneAt() error = %v", err)
	}
	if strings.Contains(got.Jar, "old=v1") {
		t.Errorf("Jar = %q, want cookie expiring before now dropped", got.Jar)
	}
}
